    @Test
    void visitTokenReproducedTest() {
        HashSet<Object> v = new HashSet<Object>();
        v.add("LITERAL_ASSERT");
        v.add("LITERAL_SWITCH");
        v.add("BOR_ASSIGN");
        v.add("LT");
        v.add("SL_ASSIGN");
        v.add("MINUS");
        v.add("BSR_ASSIGN");
        v.add("BSR");
        v.add("TYPE_EXTENSION_AND");
        v.add("BOR");
        v.add("BXOR");
        v.add("LITERAL_SYNCHRONIZED");
        v.add("PLUS_ASSIGN");
        v.add("LITERAL_CATCH");
        v.add("LITERAL_IF");
        v.add("BAND");
        v.add("SR_ASSIGN");
        v.add("LOR");
        v.add("LAMBDA");
        v.add("STAR_ASSIGN");
        v.add("BXOR_ASSIGN");
        v.add("DO_WHILE");
        v.add("LITERAL_WHILE");
        v.add("PLUS");
        v.add("LITERAL_WHEN");
        v.add("DIV_ASSIGN");
        v.add("SLIST");
        v.add("LAND");
        v.add("LITERAL_ELSE");
        v.add("LITERAL_FINALLY");
        v.add("ASSIGN");
        v.add("QUESTION");
        v.add("LITERAL_RETURN");
        v.add("SL");
        v.add("LITERAL_DO");
        v.add("GE");
        v.add("RCURLY");
        v.add("SR");
        v.add("BAND_ASSIGN");
        v.add("MOD");
        v.add("EQUAL");
        v.add("LCURLY");
        v.add("COLON");
        v.add("LITERAL_TRY");
        v.add("MINUS_ASSIGN");
        v.add("GT");
        v.add("DIV");
        v.add("MOD_ASSIGN");
        v.add("STAR");
        v.add("LITERAL_FOR");
        DefaultConfiguration v1 = new DefaultConfiguration("WhitespaceAround");
        ReflectionTestUtils.setField(v1, "name", "WhitespaceAround");
        ReflectionTestUtils.setField(v1, "propertyMap", Map.of("allowEmptyConstructors", "true", "ignoreEnhancedForColon", "false", "allowEmptyLambdas", "true", "allowEmptyMethods", "true", "allowEmptyLoops", "true", "allowEmptySwitchBlockStatements", "true", "tokens", "ASSIGN, BAND, BAND_ASSIGN, BOR, BOR_ASSIGN, BSR, BSR_ASSIGN, BXOR,                     BXOR_ASSIGN, COLON, DIV, DIV_ASSIGN, DO_WHILE, EQUAL, GE, GT, LAMBDA, LAND,                     LCURLY, LE, LITERAL_CATCH, LITERAL_DO, LITERAL_ELSE, LITERAL_FINALLY,                     LITERAL_FOR, LITERAL_IF, LITERAL_RETURN, LITERAL_SWITCH, LITERAL_SYNCHRONIZED,                     LITERAL_TRY, LITERAL_WHILE, LOR, LT, MINUS, MINUS_ASSIGN, MOD, MOD_ASSIGN,                     NOT_EQUAL, PLUS, PLUS_ASSIGN, QUESTION, RCURLY, SL, SLIST, SL_ASSIGN, SR,                     SR_ASSIGN, STAR, STAR_ASSIGN, LITERAL_ASSERT,                     TYPE_EXTENSION_AND, LITERAL_WHEN", "allowEmptyTypes", "true"));
        ReflectionTestUtils.setField(v1, "messages", Map.of("ws.notPreceded", "WhitespaceAround: ''{0}'' is not preceded with whitespace.", "ws.notFollowed", "WhitespaceAround: ''{0}'' is not followed by whitespace. Empty blocks                may only be represented as '{}' when not part of a multi-block statement (4.1.3)"));
        ReflectionTestUtils.setField(v1, "threadModeSettings", new ThreadModeSettings(1, 1));
        WhitespaceAroundCheck v2 = new WhitespaceAroundCheck();
        ReflectionTestUtils.setField(v2, "allowEmptyConstructors", true);
        ReflectionTestUtils.setField(v2, "allowEmptyMethods", true);
        ReflectionTestUtils.setField(v2, "allowEmptyTypes", true);
        ReflectionTestUtils.setField(v2, "allowEmptyLoops", true);
        ReflectionTestUtils.setField(v2, "allowEmptyLambdas", true);
        ReflectionTestUtils.setField(v2, "allowEmptyCatches", false);
        ReflectionTestUtils.setField(v2, "allowEmptySwitchBlockStatements", true);
        ReflectionTestUtils.setField(v2, "ignoreEnhancedForColon", false);
        SuppliedThreadLocal<Object> mocked = Mockito.mock(SuppliedThreadLocal.class);
        Mockito.when(mocked.get()).thenReturn(Mockito.mock(Object.class));
        ReflectionTestUtils.setField(v2, "context", mocked);
        ReflectionTestUtils.setField(v2, "tokens", v);
        ReflectionTestUtils.setField(v2, "tabWidth", 8);
        ReflectionTestUtils.setField(v2, "severityLevel", SeverityLevel.WARNING);
        ReflectionTestUtils.setField(v2, "configuration", v1);
        DetailAstImpl mocked1 = Mockito.mock(DetailAstImpl.class);
        Mockito.when(mocked1.getType()).thenReturn(72);
        DetailAstImpl mocked2 = Mockito.mock(DetailAstImpl.class);
        Mockito.when(mocked2.getType()).thenReturn(6);
        Mockito.when(mocked2.getParent()).thenReturn(Mockito.mock(DetailAstImpl.class));
        Mockito.when(mocked2.getFirstChild()).thenReturn(mocked1);
        Mockito.when(mocked1.getParent()).thenReturn(mocked2);
        Mockito.when(mocked1.getNextSibling()).thenReturn(Mockito.mock(DetailAstImpl.class));
        Mockito.when(mocked1.getPreviousSibling()).thenReturn(null).thenReturn(null);
        Mockito.when(mocked1.getLineNo()).thenReturn(7);
        Mockito.when(mocked1.getColumnNo()).thenReturn(41);
        Mockito.when(mocked1.getText()).thenReturn("{");
        v2.visitToken(mocked1);
    }

